const defaultArgs = {
  checked: false,
  partial: false,
  disabled: false,
  hasError: false,
  size: null,
  onChange: action('onSelect')
};

const Template = (args) => ({
  template: hbs`
    <OSS::Checkbox
      @checked={{this.checked}}
      @partial={{this.partial}}
      @disabled={{this.disabled}}
      @size={{this.size}}
      @hasError={{this.hasError}}
      @onChange={{this.onChange}}
    />
  `,
  context: args
});

export const Default = Template.bind({});
Default.args = defaultArgs;
